package abstraction_interfaces.assigment_problems;

import java.util.*;public class MovieTicketCounter {abstract static class Ticket{static final double FEE=20;int count;Ticket(int c){count=c;}abstract double price();double amount(){return count*(price()+FEE);}}static class Regular extends Ticket{Regular(int c){super(c);}double price(){return 150;}}static class Premium extends Ticket{Premium(int c){super(c);}double price(){return 250;}}static class Recliner extends Ticket{Recliner(int c){super(c);}double price(){return 400;}}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next();int c=s.nextInt();Ticket b=t.equals("REGULAR")?new Regular(c):t.equals("PREMIUM")?new Premium(c):new Recliner(c);double a=b.amount();System.out.printf(Locale.US,"%s: %.2f%n",t,a);total+=a;}System.out.printf(Locale.US,"Total: %.2f%n",total);}}
